import{_ as l,l as r,o as t,c as s,v as e,p as n,x as o,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"ML 热点预测","description":"","frontmatter":{"title":"ML 热点预测","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ml-hotspot-prediction.md","filePath":"litho/ml-hotspot-prediction.md","lastUpdated":1789023840000}'),c={name:"litho/ml-hotspot-prediction.md"};function E(m,a,A,_,C,L){const i=r("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="ml-热点预测" tabindex="-1">ML 热点预测 <a class="header-anchor" href="#ml-热点预测" aria-label="Permalink to &quot;ML 热点预测&quot;">​</a></h1><div class="epigraph"><p>学习模型可以给全场 clips 打风险分，让严格前向与人工复检先看见高分者；它预测的是排序，不是另一套麦克斯韦。</p><footer>—— 对照计算光刻中机器学习热点检测的公开讨论；与 [ML OPC](/litho/ml-opc) 的前向近似分工</footer></div><p><a href="/litho/lrc-orc">上一课</a>要求过程角全场检查。缺口是墙钟与漏检权衡：角一多，LRC 尾延迟炸；角一少，新拓扑漏。本课钉机器学习热点预测：用历史 LRC/PWQ 标签训练，给新版图 clips 打分。<a href="/litho/decomposition-coloring-conflict">分解着色</a> 下一课回到确定性规则冲突，不在这里用网络代替染色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/ml-opc">ML OPC</a> 已经声明学习模型最多近似前向，签核仍要物理核。热点预测更窄：输入局部多边形（或密度图），输出「是否像会在 PV-band 越界」。它服务<strong>调度</strong>——先仿真高分 clips、先修高分单元——而不是颁发绿灯。</p><p>缺口是<strong>标签与漂移</strong>，不是网络结构竞赛。换胶、换光源、换分解，标签分布移位，旧模型会把真热点打到低分。把预测当 LRC 替代，等于用过期残差图签核。</p><h3 id="排序不是判决" tabindex="-1">排序不是判决 <a class="header-anchor" href="#排序不是判决" aria-label="Permalink to &quot;排序不是判决&quot;">​</a></h3><p>AUC 好看只说明相对顺序有用。规格是绝对的：某一 clip 在离焦 40 nm 是否桥连，仍要核或硅。把 softmax 阈值写进 DRC 手册，版本无法审计。允许的用法：匹配课的模板不够时，用模型挖「不像旧杀手、但高风险」的新物种，再送 LRC。</p><p><span class="marginnote">训练集约等于 PWQ 失败点加 LRC 历史。类别极不均衡。报准确率无意义，看召回与校准曲线，并留时间外保持集。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>特征：密度图、几何描述子、或图像化 clips。标签：LRC 越界、PWQ 缺陷、有时 AEI 失败。协议：与 OPC 模型同节点同层训练；工艺改版即重训或至少重校准。部署：全场滑动窗打分 → 顶 k% 升格全角 LRC 或严格 EMF。与图形匹配互补：匹配高召回已知拓扑，ML 补分布外的相似形。</p><p>禁止：用预测 CD 替代计量；用预测套刻替代对准。那是虚拟计量课的范围，且仍不能当法律量。</p><p>部署后要盯校准：每周用新 LRC 标签画可靠性图，一旦低分里出现 PWQ 真杀手，立刻关自动调度、回退到全角抽样。计算光刻里 ML 热点检测的公开讨论，几乎都把「辅助排序」写进摘要，把「替代签核」留在未发表的愿望里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>局部可印性大致是邻域算子，故卷积神经网络或图网络能拟合「这类 jog 在该核下危险」。它拟合的是核+历史的复合，不是成像物理。域偏移来自核更新和设计风格漂移（新库、新轨道）。校准曲线一旦变平，调度仍可参考，判决必须关掉。</p>',15)),(t(),n(h,null,{default:o(()=>[d(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIST%5B%22LRC%20%2F%20PWQ%20%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20TR%5B%22%E8%AE%AD%E7%BB%83%E9%A3%8E%E9%99%A9%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20LAY%5B%22%E6%96%B0%E7%89%88%E5%9B%BE%20clips%22%5D%20--%3E%20SCORE%5B%22%E9%A3%8E%E9%99%A9%E5%88%86%22%5D%0A%20%20TR%20--%3E%20SCORE%0A%20%20SCORE%20--%3E%20TOP%5B%22%E9%A1%B6%20k%25%20%E5%8D%87%E6%A0%BC%20LRC%22%5D%0A%20%20TOP%20--%3E%20GATE%5B%22%E7%89%A9%E7%90%86%E6%A0%B8%E7%AD%BE%E6%A0%B8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进入限价簿，也不把 Transformer 训练当光刻签核。不发明 arXiv 编号或未公开的「全芯片 ML 替代 LRC」。随机光子缺陷的标签噪声大，ML 召回不可当随机窗。</p><p>后课默认：ML 只排序；绿灯仍是 LRC。下一课处理多重分解里确定性的着色冲突——那不是预测问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>热点预测给 clips 排序以调度仿真，不替代 LRC 判决。</li><li>标签与工艺版本绑定；漂移则模型作废。</li><li>与模板匹配分工：已知拓扑对学习补新物种。</li><li>出处：计算光刻 ML 热点检测公开讨论；ML OPC 课已划的签核边界。</li></ul>',5))])}const u=l(c,[["render",E]]);export{P as __pageData,u as default};
